async function init(){const params=new URLSearchParams(location.search),manifestPath=params.get('manifest')||'rdx/data/soundlab/manifest.json',serviceBase=params.get('service');state.manifestUrl=new URL(manifestPath,document.baseURI);const response=await fetch(state.manifestUrl,{cache:'no-store'});if(!response.ok)throw new Error(`SoundLab manifest load failed (${response.status})`);state.manifest=assertSoundLabManifest(await response.json());$('sl-project').textContent=`${state.manifest.project} · ${state.manifest.rendererVersion}`;$('sl-renderer').textContent=state.manifest.rendererVersion;$('sl-build-state').textContent=`${state.manifest.outputs.length} promoted outputs`;populateCases();setBinding(state.manifest.bindings[0]?.id);configureNativeInput();installPersistedDetails();installWorkspace();loadPressureCalibration();installEvents();await connectAuthoringService(serviceBase);document.documentElement.dataset.soundlabReady='true';}
if(typeof document!=='undefined'&&document.getElementById('soundlab-app'))init().catch(error=>{$('sl-project').textContent=error.message;document.documentElement.dataset.soundlabError=error.message;console.error(error);});

